def first_or_none(items):
    if len(items) == 0:
        return None
    return items[0]

print(first_or_none(['Radio', 'Printer']))

def last_or_none(items):
    if len(items) == 0:
        return None
    return items[-1]

print(last_or_none([3, 7, 2]))

def first_jobs(jobs, count):
    return jobs[:count]

print(first_jobs(['A', 'B', 'C'], 2))

def remove_last(queue):
    if len(queue) == 0:
        return None
    return queue.pop()

sample = ['A', 'B']
result = remove_last(sample)
print(result)
print(sample)

