def positive_lengths(lengths):
    accepted = []
    for length in lengths:
        if length > 0:
            accepted.append(length)
    return accepted

print(positive_lengths([0, 8, -1, 3]))

def numbered_labels(names):
    labels = []
    for number, name in enumerate(names, start=1):
        labels.append(f"{number}: {name}")
    return labels

print(numbered_labels(['Radio', 'Printer']))

def contains_label(names, target):
    return target in names

print(contains_label(['Radio', 'Printer'], 'Radio'))

def double_readings(values):
    return [value * 2 for value in values]

print(double_readings([1, 0, -2]))

